def solve(tables):
    df = tables["expenses"].copy()

    if df.empty:
        return pd.DataFrame(columns=["paid_by", "share_pct"])

    totals = df.groupby("paid_by", as_index=False)["amount_inr"].sum()
    grand_total = totals["amount_inr"].sum()

    if grand_total == 0:
        totals["share_pct"] = 0.0
    else:
        totals["share_pct"] = (totals["amount_inr"] / grand_total * 100).round(1)

    return totals[["paid_by", "share_pct"]]
```

