def solve(tables):
    shipments = tables["shipments"]
    carriers = tables["carriers"]

    carrier_ratings = (
        carriers[["carrier", "rating"]]
        .drop_duplicates(subset=["carrier"], keep="first")
    )

    merged = shipments.merge(carrier_ratings, on="carrier", how="left")
    avg_rating = merged["rating"].mean()

    if pd.isna(avg_rating):
        avg_rating = None
    else:
        avg_rating = round(float(avg_rating), 1)

    return pd.DataFrame({"avg_rating": [avg_rating]})
```

