def solve(tables):
    df = tables["requests"].copy()

    if df.empty:
        return pd.DataFrame(columns=["endpoint", "success_pct"])

    status = pd.to_numeric(df["status"], errors="coerce")
    success = (status >= 200) & (status <= 299)

    tmp = pd.DataFrame({
        "endpoint": df["endpoint"],
        "success": success
    })

    out = tmp.groupby("endpoint", as_index=False).agg(
        total=("success", "size"),
        success_count=("success", "sum")
    )

    out["success_pct"] = (out["success_count"] / out["total"] * 100).round(1)
    out = out[["endpoint", "success_pct"]].sort_values("endpoint").reset_index(drop=True)

    return out
```

